vertexShader:
attribute vec4 aSeed; attribute float aSrc; uniform float uTime, uH, uAlive[8]; varying float vA;
void main() {
  float life = aSeed.w, tt = fract(uTime / life + aSeed.x) ;
  vec3 p = position + vec3(sin(aSeed.y * 40. + tt * 3.) * 4. * tt, tt * aSeed.z, cos(aSeed.y * 33. + tt * 2.) * 4. * tt) + vec3(tt * tt * 18., 0., tt * tt * 6.);
  vec4 mv = viewMatrix * vec4(p, 1.); gl_Position = projectionMatrix * mv;
  gl_PointSize = min((6. + 26. * tt) * projectionMatrix[1][1] * uH * .5 / max(-mv.z, 1.), 400.);
  vA = smoothstep(0., .12, tt) * (1. - smoothstep(.55, 1., tt)) * uAlive[int(aSrc + .5)];
}

fragmentShader:
uniform sampler2D map; uniform vec3 uCol; varying float vA;
void main() { vec4 t = texture2D(map, gl_PointCoord); gl_FragColor = vec4(uCol, t.a * vA * .55);
  #include <colorspace_fragment>
}
